def page(n, kicker, title, body): return f'<section class="page"><header><span class="kick">{e(kicker)}</span><h1>{e(title)}</h1></header><div class="content">{body}</div><footer><span>Οδηγός διδάσκοντος · δεν διανέμεται στους φοιτητές</span><span>Εργαστήριο 1 · σελίδα {n} από {NP}</span></footer></section>'
