names = {'R1': 'Συνδέσεις ≤ 8', 'R2': 'Υποβολές ≤ 15', 'R3': 'P(E→S) < 0,35', 'R4': 'Φύλλα εμπρόθεσμα ≤ 2', 'R3m': 'P(E→S) < 0,35 ή ανεπαρκή δεδομένα', 'R5': 'Φύλλα εξαμήνου ≤ 6 (μη διαθέσιμο)', 'R6': 'Πρόοδος < 5 ή απουσία (μη διαθέσιμο)'}
def nm(k):
    for a, b in (('R3m', 'ΑΑΑ'),): k = k.replace(a, b)
    for a in ('R1', 'R2', 'R3', 'R4', 'R5', 'R6'): k = k.replace(a, '«' + names[a].split(' (')[0] + '»')
    return k.replace('ΑΑΑ', '«' + names['R3m'] + '»')
def lrow(k, label=None, bold=False):
    a = LK[k]; b = TK[k]; lab = label or (names[k] if k in names else nm(k)); o = '<b>' if bold else ''; c = '</b>' if bold else ''
    return f"<tr><td>{o}{e(lab)}{c}</td><td>{pc(a['flagged_p'])}</td><td>{pc(a['recall'])}</td><td>{pc(a['precision'])}</td><td>{o}{pc(a['acc'])}{c}</td><td>{pc(b['flagged_p'])}</td><td>{pc(b['recall'])}</td><td>{pc(b['precision'])}</td><td>{o}{pc(b['acc'])}{c}</td></tr>"
singles = ''.join(lrow(k) for k in ['R1', 'R2', 'R3', 'R4', 'R3m'])
pairs = ''.join(lrow(k, bold=(k == 'R3 ή R4')) for k in LK if (' ή ' in k or ' και ' in k))
